#requires -Version 7.4
# Generated by DSR. Configuration is data; downloaded payloads are never executed.
# Requires PowerShell 7.4+ and Windows. Cooperating installers share a kernel lock.
[CmdletBinding()]
param(
    [string]$Version = '',
    [string]$Prefix = '',
    [string]$CacheDir = '',
    [switch]$Offline,
    [switch]$Yes,
    [switch]$Json,
    [switch]$Help
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$script:DsrWindowsInstallPolicyBase64 = '__DSR_WINDOWS_INSTALL_POLICY_B64__'
$script:DsrMaximumPayloadBytes = 2147483648L
$script:DsrMaximumExpandedBytes = 4294967296L

function Stop-DsrInstall {
    param([string]$Message, [int]$Code = 4)
    $failure = [System.InvalidOperationException]::new($Message)
    $failure.Data['DsrExitCode'] = $Code
    throw $failure
}

function Write-DsrInstallLog {
    param([string]$Message)
    [Console]::Error.WriteLine('[dsr installer] ' + $Message)
}

function Write-DsrInstallVerbose {
    param([string]$Message)
    if ($VerbosePreference -eq [Management.Automation.ActionPreference]::Continue) { Write-DsrInstallLog $Message }
}

function Test-DsrName {
    param($Value)
    return $Value -is [string] -and $Value -cmatch '^[A-Za-z0-9][A-Za-z0-9._+-]{0,239}$' -and
        -not $Value.Contains('..')
}

function Test-DsrWindowsName {
    param($Value)
    return (Test-DsrName $Value) -and -not $Value.EndsWith('.') -and
        $Value -inotmatch '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)'
}

function Assert-DsrFields {
    param($Value, [string[]]$Required, [string[]]$Optional = @())
    if ($Value -isnot [System.Collections.IDictionary]) { Stop-DsrInstall 'Expected a JSON object' }
    foreach ($name in $Required) {
        if (-not $Value.Contains($name)) { Stop-DsrInstall ('Missing policy field: ' + $name) }
    }
    foreach ($name in $Value.Keys) {
        if ($name -cnotin $Required -and $name -cnotin $Optional) {
            Stop-DsrInstall ('Unknown policy field: ' + $name)
        }
    }
}

function Assert-DsrJsonKeys {
    param([System.Text.Json.JsonElement]$Element)
    if ($Element.ValueKind -eq [System.Text.Json.JsonValueKind]::Object) {
        $names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($property in $Element.EnumerateObject()) {
            if (-not $names.Add($property.Name)) { Stop-DsrInstall 'Duplicate JSON key' }
            Assert-DsrJsonKeys $property.Value
        }
    } elseif ($Element.ValueKind -eq [System.Text.Json.JsonValueKind]::Array) {
        foreach ($item in $Element.EnumerateArray()) { Assert-DsrJsonKeys $item }
    }
}

function ConvertFrom-DsrJson {
    param([string]$Text)
    $document = $null
    try {
        $document = [System.Text.Json.JsonDocument]::Parse($Text)
        Assert-DsrJsonKeys $document.RootElement
        # Keep empty and singleton API pages as arrays. PowerShell's normal
        # pipeline enumeration would turn [] into null and [row] into row.
        return ,(ConvertFrom-Json -InputObject $Text -AsHashtable -Depth 64 -NoEnumerate)
    } finally {
        if ($null -ne $document) { $document.Dispose() }
    }
}

function Get-DsrBytesHash {
    param([byte[]]$Bytes)
    return [Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData($Bytes)).ToLowerInvariant()
}

function Get-DsrInstallPolicy {
    $bytes = [Convert]::FromBase64String($script:DsrWindowsInstallPolicyBase64)
    if ($bytes.Length -eq 0 -or $bytes.Length -gt 1048576) { Stop-DsrInstall 'Invalid embedded installer policy size' }
    $encoding = [System.Text.UTF8Encoding]::new($false, $true)
    $policy = ConvertFrom-DsrJson $encoding.GetString($bytes)
    Assert-DsrFields $policy @('schema_version', 'tool', 'repo', 'binary_name', 'public_key', 'platforms')
    if (($policy.schema_version -isnot [long] -and $policy.schema_version -isnot [int]) -or
        $policy.schema_version -ne 1 -or -not (Test-DsrName $policy.tool) -or
        -not (Test-DsrName $policy.binary_name) -or $policy.repo -isnot [string] -or
        $policy.repo -cnotmatch '^[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*$' -or
        $policy.public_key -isnot [string] -or
        $policy.platforms -isnot [System.Collections.IDictionary] -or $policy.platforms.Count -lt 1) {
        Stop-DsrInstall 'Invalid embedded Windows installer policy'
    }
    if ($policy.public_key) {
        if ($policy.public_key -cnotmatch '^[A-Za-z0-9+/]{56}$' -or
            [Convert]::FromBase64String($policy.public_key).Length -ne 42) {
            Stop-DsrInstall 'Invalid embedded Minisign public key'
        }
    }
    foreach ($platform in $policy.platforms.Keys) {
        if ($platform -cnotin @('windows/amd64', 'windows/arm64', 'windows/386')) {
            Stop-DsrInstall ('Unsupported configured Windows platform: ' + $platform)
        }
        $selection = $policy.platforms[$platform]
        Assert-DsrFields $selection @('name', 'format', 'binaries', 'target_triple')
        if ($selection.name -isnot [string] -or
            -not (Test-DsrWindowsName $selection.name.Replace('${version}', '1.2.3')) -or
            $selection.format -cnotin @('zip', 'none') -or
            $selection.binaries -isnot [array] -or $selection.binaries.Count -lt 1 -or
            $selection.binaries.Count -gt 64 -or $selection.target_triple -isnot [string] -or
            ($selection.target_triple -and -not (Test-DsrName $selection.target_triple))) {
            Stop-DsrInstall ('Invalid Windows payload selection: ' + $platform)
        }
        if ($selection.format -ceq 'none' -and $selection.binaries.Count -ne 1) {
            Stop-DsrInstall 'A raw Windows payload must select exactly one executable'
        }
        $names = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        foreach ($name in $selection.binaries) {
            if (-not (Test-DsrWindowsName $name) -or $name.Length -gt 200 -or
                -not $name.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase) -or
                -not $names.Add($name)) { Stop-DsrInstall 'Invalid or colliding Windows executable family' }
        }
        $primary = $policy.binary_name
        if (-not $primary.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase)) { $primary += '.exe' }
        if (-not $names.Contains($primary)) { Stop-DsrInstall 'Executable family does not include its primary binary' }
    }
    return @{ value = $policy; sha256 = (Get-DsrBytesHash $bytes) }
}

function Get-DsrHostPlatform {
    if (-not [System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        Stop-DsrInstall 'This installer requires native Windows and PowerShell 7.4 or newer' 3
    }
    switch ([System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture.ToString()) {
        'X64' { return 'windows/amd64' }
        'Arm64' { return 'windows/arm64' }
        'X86' { return 'windows/386' }
        default { Stop-DsrInstall 'Unsupported native Windows architecture' 3 }
    }
}

function Get-DsrPlainPath {
    param([string]$Path, [switch]$Directory, [switch]$File, [switch]$AllowRoot)
    if (-not $Path -or -not [IO.Path]::IsPathFullyQualified($Path) -or
        $Path -match '[\x00-\x1f\x7f]' -or $Path -match '(^|[\\/])\.{1,2}([\\/]|$)' -or
        $Path.StartsWith('\\') -or $Path.StartsWith('//')) {
        Stop-DsrInstall 'Use an absolute local path without dot components or control characters'
    }
    $canonical = [IO.Path]::GetFullPath($Path)
    $full = $canonical.TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar)
    if (-not $full -or $full -eq [IO.Path]::GetPathRoot($canonical).TrimEnd('\', '/')) {
        if (-not $AllowRoot) { Stop-DsrInstall 'A filesystem root cannot be an installer destination' }
        $full = [IO.Path]::GetPathRoot($canonical)
    }
    $cursor = $full
    while ($cursor) {
        try { $attributes = [IO.File]::GetAttributes($cursor) }
        catch [IO.FileNotFoundException] { $attributes = $null }
        catch [IO.DirectoryNotFoundException] { $attributes = $null }
        if ($null -ne $attributes) {
            if (($attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Stop-DsrInstall 'A selected path contains a link or reparse point' 7 }
            if ($cursor -ne $full -and ($attributes -band [IO.FileAttributes]::Directory) -eq 0) {
                Stop-DsrInstall 'A selected path contains a non-directory ancestor' 7
            }
        }
        $next = [IO.Path]::GetDirectoryName($cursor)
        if ($next -eq $cursor) { break }
        $cursor = $next
    }
    if ($Directory -and -not [IO.Directory]::Exists($full)) { Stop-DsrInstall 'Required directory is missing' 7 }
    if ($File -and -not [IO.File]::Exists($full)) { Stop-DsrInstall 'Required regular file is missing' 7 }
    return $full
}

function Test-DsrPathsOverlap {
    param([string]$Left, [string]$Right)
    $separator = [IO.Path]::DirectorySeparatorChar
    return $Left.Equals($Right, [StringComparison]::OrdinalIgnoreCase) -or
        $Left.StartsWith($Right + $separator, [StringComparison]::OrdinalIgnoreCase) -or
        $Right.StartsWith($Left + $separator, [StringComparison]::OrdinalIgnoreCase)
}

function New-DsrPrivateDirectory {
    param([string]$Path)
    $pathValue = Get-DsrPlainPath $Path
    if ([IO.Directory]::Exists($pathValue) -or [IO.File]::Exists($pathValue)) { Stop-DsrInstall 'Private staging path already exists' 2 }
    $parent = [IO.Path]::GetDirectoryName($pathValue)
    $null = Get-DsrPlainPath $parent -Directory -AllowRoot
    if ([System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User
        $acl = [Security.AccessControl.DirectorySecurity]::new()
        $acl.SetOwner($sid)
        $acl.SetAccessRuleProtection($true, $false)
        $rule = [Security.AccessControl.FileSystemAccessRule]::new($sid, [Security.AccessControl.FileSystemRights]::FullControl,
            [Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit',
            [Security.AccessControl.PropagationFlags]::None, [Security.AccessControl.AccessControlType]::Allow)
        $acl.AddAccessRule($rule)
        [IO.FileSystemAclExtensions]::Create([IO.DirectoryInfo]::new($pathValue), $acl)
    } else {
        # This branch permits genuine PowerShell integration tests on POSIX;
        # Get-DsrHostPlatform still rejects non-Windows production execution.
        $null = [IO.Directory]::CreateDirectory($pathValue)
        [IO.File]::SetUnixFileMode($pathValue, [IO.UnixFileMode]'UserRead,UserWrite,UserExecute')
    }
    return Get-DsrPlainPath $pathValue -Directory
}

function New-DsrDirectoryChain {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path
    if ([IO.Directory]::Exists($full)) { return $full }
    $pending = [Collections.Generic.List[string]]::new()
    $cursor = $full
    while (-not [IO.Directory]::Exists($cursor)) {
        $pending.Add($cursor)
        $cursor = [IO.Path]::GetDirectoryName($cursor)
        if (-not $cursor) { Stop-DsrInstall 'Missing filesystem root' }
    }
    for ($index = $pending.Count - 1; $index -ge 0; $index--) {
        $null = New-DsrPrivateDirectory $pending[$index]
    }
    return Get-DsrPlainPath $full -Directory
}

function New-DsrPrivateFile {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path
    $null = Get-DsrPlainPath ([IO.Path]::GetDirectoryName($full)) -Directory -AllowRoot
    if ([System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        # Elevated Windows tokens can default a new file's owner to the
        # Administrators group. Set the exact user and private ACL atomically
        # at CreateNew, preserving strict ownership checks on existing cache.
        $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User
        $acl = [Security.AccessControl.FileSecurity]::new()
        $acl.SetOwner($sid)
        $acl.SetAccessRuleProtection($true, $false)
        $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,
            [Security.AccessControl.FileSystemRights]::FullControl, [Security.AccessControl.AccessControlType]::Allow))
        return [IO.FileSystemAclExtensions]::Create([IO.FileInfo]::new($full), [IO.FileMode]::CreateNew,
            [Security.AccessControl.FileSystemRights]::FullControl, [IO.FileShare]::None, 4096,
            [IO.FileOptions]::None, $acl)
    }
    # The POSIX integration adapter exercises exclusive private creation too;
    # it does not substitute or qualify the Windows owner/ACL implementation.
    $options = [IO.FileStreamOptions]::new()
    $options.Mode = [IO.FileMode]::CreateNew
    $options.Access = [IO.FileAccess]::ReadWrite
    $options.Share = [IO.FileShare]::None
    $options.UnixCreateMode = [IO.UnixFileMode]'UserRead,UserWrite'
    return [IO.FileStream]::new($full, $options)
}

function Assert-DsrCacheCustody {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path
    if ([System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) {
        $current = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
        $trusted = @($current, 'S-1-5-18', 'S-1-5-32-544',
            'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')
        $cursor = $full
        $selected = $true
        while ($cursor) {
            $item = if ([IO.Directory]::Exists($cursor)) { [IO.DirectoryInfo]::new($cursor) } else { [IO.FileInfo]::new($cursor) }
            $acl = [IO.FileSystemAclExtensions]::GetAccessControl($item)
            $owner = $acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
            if (($selected -and $owner -cne $current) -or (-not $selected -and $owner -cnotin $trusted)) {
                Stop-DsrInstall 'Download cache ownership is not private to the current user' 7
            }
            $descriptor = [Security.AccessControl.RawSecurityDescriptor]::new($acl.GetSecurityDescriptorBinaryForm(), 0)
            if ($null -eq $descriptor.DiscretionaryAcl) { Stop-DsrInstall 'Download cache has an unrestricted access list' 7 }
            foreach ($rule in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
                if ($rule.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow -or
                    ($rule.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly) -ne 0 -or
                    $rule.IdentityReference.Value -cin $trusted) { continue }
                # Ancestors may permit creating unrelated names, but must not
                # permit replacing this cache directory or rewriting its ACL.
                $mask = [long][Security.AccessControl.FileSystemRights]'Delete,DeleteSubdirectoriesAndFiles,ChangePermissions,TakeOwnership'
                if ($selected) { $mask = $mask -bor [long][Security.AccessControl.FileSystemRights]'Write,Delete' }
                if (([long]$rule.FileSystemRights -band $mask) -ne 0) {
                    Stop-DsrInstall 'Download cache permits modification by another principal' 7
                }
            }
            $selected = $false
            $next = [IO.Path]::GetDirectoryName($cursor)
            if ($next -eq $cursor) { break }
            $cursor = $next
        }
    } else {
        # Only reached by the explicit POSIX integration-test host adapter.
        # Native execution is guarded by Get-DsrHostPlatform.
        $mode = [IO.File]::GetUnixFileMode($full)
        $foreignWrites = [IO.UnixFileMode]'GroupWrite,OtherWrite'
        if (($mode -band $foreignWrites) -ne 0) { Stop-DsrInstall 'Download cache is writable by other users' 7 }
    }
}

function Open-DsrReadFile {
    param([string]$Path)
    $full = Get-DsrPlainPath $Path -File
    return [IO.FileStream]::new($full, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
}

function Get-DsrFileEvidence {
    param([string]$Path)
    $stream = Open-DsrReadFile $Path
    try {
        $size = $stream.Length
        $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream)).ToLowerInvariant()
        if ($stream.Length -ne $size) { Stop-DsrInstall 'File size changed during verification' 7 }
        return @{ sha256 = $hash; size_bytes = $size }
    } finally { $stream.Dispose() }
}

function Read-DsrTextFile {
    param([string]$Path, [long]$Limit = 8388608)
    $stream = Open-DsrReadFile $Path
    try {
        if ($stream.Length -gt $Limit) { Stop-DsrInstall 'Metadata exceeds its size limit' 7 }
        $reader = [IO.StreamReader]::new($stream, [Text.UTF8Encoding]::new($false, $true), $true, 4096, $true)
        try { return $reader.ReadToEnd() } finally { $reader.Dispose() }
    } finally { $stream.Dispose() }
}

function Write-DsrNewTextFile {
    param([string]$Path, [string]$Text)
    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($Text)
    $stream = New-DsrPrivateFile $Path
    try { $stream.Write($bytes, 0, $bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
}

function Copy-DsrNewFile {
    param([string]$Source, [string]$Destination)
    $incoming = Open-DsrReadFile $Source
    try {
        $outgoing = New-DsrPrivateFile $Destination
        try { $incoming.CopyTo($outgoing); $outgoing.Flush($true) } finally { $outgoing.Dispose() }
    } finally { $incoming.Dispose() }
}

function Remove-DsrPrivateTree {
    param([string]$Path)
    if (-not $Path -or -not [IO.Directory]::Exists($Path)) { return }
    $null = Get-DsrPlainPath $Path -Directory
    foreach ($entry in [IO.DirectoryInfo]::new($Path).EnumerateFileSystemInfos()) {
        if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            Stop-DsrInstall ('Private staging changed; retained for inspection: ' + $Path) 7
        }
        if (($entry.Attributes -band [IO.FileAttributes]::Directory) -ne 0) { Remove-DsrPrivateTree $entry.FullName }
        else { [IO.File]::Delete($entry.FullName) }
    }
    [IO.Directory]::Delete($Path, $false)
}

function Get-DsrGitHubToken {
    foreach ($variable in @('DSR_GH_TOKEN', 'GITHUB_TOKEN', 'GH_TOKEN')) {
        $candidate = [Environment]::GetEnvironmentVariable($variable)
        if ($candidate) {
            if ($candidate -match '[\x00-\x20\x7f]') { Stop-DsrInstall 'Invalid selected GitHub credential' 4 }
            return $candidate
        }
    }
    return ''
}

function New-DsrHttpClient {
    $handler = [Net.Http.HttpClientHandler]::new()
    $handler.AllowAutoRedirect = $false
    $handler.UseCookies = $false
    # Disposing this client also disposes its exclusively owned handler.
    $client = [Net.Http.HttpClient]::new($handler, $true)
    $client.Timeout = [Threading.Timeout]::InfiniteTimeSpan
    return $client
}

function Invoke-DsrDownload {
    param([string]$Url, [string]$Destination, [switch]$Optional, [long]$MaximumBytes = 2147483648,
          [switch]$ApiAsset)
    $uri = [Uri]$Url
    if ($uri.Scheme -cne 'https' -or $uri.Host -cnotin @('github.com', 'api.github.com') -or
        -not $uri.IsDefaultPort -or $uri.UserInfo -or $uri.Fragment) {
        Stop-DsrInstall 'Invalid GitHub acquisition URL' 4
    }
    if ($ApiAsset -and ($uri.Host -cne 'api.github.com' -or
        $uri.AbsolutePath -cnotmatch '^/repos/[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*/releases/assets/[1-9][0-9]*$')) {
        Stop-DsrInstall 'Invalid GitHub release-asset API URL' 4
    }
    $token = Get-DsrGitHubToken
    $apiPrefix = ''
    if ($uri.Host -ceq 'api.github.com') {
        if ($uri.AbsolutePath -cnotmatch '^(/repos/[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*/releases/)') {
            Stop-DsrInstall 'Invalid GitHub release API scope' 4
        }
        $apiPrefix = $Matches[1]
    }
    $client = New-DsrHttpClient
    $deadline = [Threading.CancellationTokenSource]::new([TimeSpan]::FromSeconds(60))
    $sendCredential = [bool]$apiPrefix
    try {
        for ($redirect = 0; $redirect -le 5; $redirect++) {
            $request = [Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Get, $uri)
            $request.Headers.UserAgent.ParseAdd('doodlestein_self_releaser-installer/1.0')
            $accept = if ($ApiAsset) { 'application/octet-stream' } else { 'application/vnd.github+json' }
            $request.Headers.Accept.ParseAdd($accept)
            $null = $request.Headers.TryAddWithoutValidation('X-GitHub-Api-Version', '2022-11-28')
            # Credentials belong only to the configured repository's API
            # requests, never browser URLs or signed object-storage redirects.
            if ($token -and $sendCredential) {
                $request.Headers.Authorization = [Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer', $token)
            }
            $response = $null
            try {
                $response = $client.SendAsync($request, [Net.Http.HttpCompletionOption]::ResponseHeadersRead,
                    $deadline.Token).GetAwaiter().GetResult()
                $status = [int]$response.StatusCode
                if ($status -in @(301, 302, 303, 307, 308)) {
                    if ($redirect -eq 5 -or $null -eq $response.Headers.Location) { Stop-DsrInstall 'Invalid or excessive download redirects' 8 }
                    $uri = [Uri]::new($uri, $response.Headers.Location)
                    if ($uri.Scheme -cne 'https' -or -not $uri.IsDefaultPort -or $uri.UserInfo -or $uri.Fragment) {
                        Stop-DsrInstall 'Refusing an unsafe download redirect' 8
                    }
                    if ($apiPrefix) {
                        $sameScope = $uri.Host -ceq 'api.github.com' -and
                            $uri.AbsolutePath.StartsWith($apiPrefix, [StringComparison]::Ordinal)
                        if ((-not $ApiAsset -or $uri.Host -ceq 'api.github.com') -and -not $sameScope) {
                            Stop-DsrInstall 'GitHub API redirect changed the selected repository' 8
                        }
                        # Once a request leaves the API scope, a redirect back
                        # cannot regain the original Authorization header.
                        $sendCredential = $sendCredential -and $sameScope
                    }
                    continue
                }
                if ($status -in @(404, 410) -and $Optional) { return $false }
                if ($status -ne 200) { Stop-DsrInstall ('GitHub download failed with HTTP ' + $status) 8 }
                if ($null -ne $response.Content.Headers.ContentLength -and $response.Content.Headers.ContentLength -gt $MaximumBytes) {
                    Stop-DsrInstall 'Download exceeds its size limit' 7
                }
                $incoming = $response.Content.ReadAsStreamAsync($deadline.Token).GetAwaiter().GetResult()
                try {
                    $outgoing = New-DsrPrivateFile $Destination
                    try {
                        $buffer = [byte[]]::new(1048576)
                        $total = 0L
                        while (($count = $incoming.ReadAsync($buffer, 0, $buffer.Length, $deadline.Token).GetAwaiter().GetResult()) -gt 0) {
                            $total += $count
                            if ($total -gt $MaximumBytes) { Stop-DsrInstall 'Download exceeds its size limit' 7 }
                            $outgoing.Write($buffer, 0, $count)
                        }
                        $outgoing.Flush($true)
                    } finally { $outgoing.Dispose() }
                } finally { $incoming.Dispose() }
                return $true
            } finally {
                if ($null -ne $response) { $response.Dispose() }
                $request.Dispose()
            }
        }
    } catch [OperationCanceledException] {
        Stop-DsrInstall 'GitHub download exceeded its complete-transfer deadline' 8
    } catch [Net.Http.HttpRequestException] {
        # Exception text can contain a signed redirect URL. Keep credentials
        # and acquisition tokens out of diagnostics and machine results.
        Stop-DsrInstall 'GitHub download failed during HTTPS transport' 8
    } finally { $deadline.Dispose(); $client.Dispose(); $token = '' }
    Stop-DsrInstall 'Download did not complete' 8
}

function Assert-DsrReleaseIdentity {
    param($Release, [string]$Tag)
    if ($Release -isnot [System.Collections.IDictionary] -or
        -not $Release.Contains('id') -or ($Release.id -isnot [long] -and $Release.id -isnot [int]) -or
        $Release.id -le 0 -or -not $Release.Contains('tag_name') -or $Release.tag_name -isnot [string] -or
        $Release.tag_name -cne $Tag -or
        -not $Release.Contains('draft') -or $Release.draft -isnot [bool] -or $Release.draft) {
        Stop-DsrInstall 'GitHub release identity does not match the selected published tag' 7
    }
}

function Get-DsrReleaseAssets {
    param([string]$Repository, [long]$ReleaseId, [string]$Directory)
    $assets = [Collections.Generic.Dictionary[string, object]]::new([StringComparer]::Ordinal)
    $ids = [Collections.Generic.HashSet[long]]::new()
    # Construct every page URL ourselves. Neither server-supplied URLs nor
    # Link headers can change repository/host or carry credentials elsewhere.
    for ($page = 1; $page -le 101; $page++) {
        $path = [IO.Path]::Combine($Directory, ('release-assets-' + $page + '.json'))
        $url = 'https://api.github.com/repos/' + $Repository + '/releases/' + $ReleaseId + '/assets?per_page=100&page=' + $page
        $null = Invoke-DsrDownload $url $path -MaximumBytes 8388608
        $rows = ConvertFrom-DsrJson (Read-DsrTextFile $path)
        if ($rows -isnot [array] -or $rows.Count -gt 100) { Stop-DsrInstall 'Malformed GitHub release asset page' 7 }
        if ($assets.get_Count() + $rows.Count -gt 10000) { Stop-DsrInstall 'GitHub release asset inventory exceeds 10000 entries' 7 }
        foreach ($row in $rows) {
            if ($row -isnot [System.Collections.IDictionary] -or
                -not $row.Contains('id') -or ($row.id -isnot [long] -and $row.id -isnot [int]) -or $row.id -le 0 -or
                -not $row.Contains('name') -or $row.name -isnot [string] -or -not $row.name -or
                $row.name.Length -gt 1024 -or $row.name -match '[\x00-\x1f\x7f]' -or
                -not $row.Contains('size') -or ($row.size -isnot [long] -and $row.size -isnot [int]) -or $row.size -lt 0 -or
                -not $row.Contains('state') -or $row.state -isnot [string]) {
                Stop-DsrInstall 'Malformed GitHub release asset identity' 7
            }
            if (-not $ids.Add($row.id) -or $assets.ContainsKey($row.name)) {
                Stop-DsrInstall 'Duplicate GitHub release asset name or identity' 7
            }
            $assets.Add($row.name, @{ id = $row.id; size = $row.size; state = $row.state })
        }
        if ($rows.Count -lt 100) { return ,$assets }
    }
    Stop-DsrInstall 'GitHub release asset inventory exceeds 10000 entries' 7
}

function Save-DsrReleaseAsset {
    param([string]$Repository, [string]$Tag, [string]$Name, [string]$Destination, $Inventory = $null,
          [switch]$Optional, [long]$MaximumBytes = 2147483648)
    if ($null -eq $Inventory) {
        $url = 'https://github.com/' + $Repository + '/releases/download/' + [Uri]::EscapeDataString($Tag) + '/' + [Uri]::EscapeDataString($Name)
        return Invoke-DsrDownload $url $Destination -Optional:$Optional -MaximumBytes $MaximumBytes
    }
    if (-not $Inventory.ContainsKey($Name)) {
        if ($Optional) { return $false }
        Stop-DsrInstall ('Selected release asset is missing: ' + $Name) 8
    }
    $asset = $Inventory[$Name]
    if ($asset.state -cne 'uploaded' -or $asset.size -le 0 -or $asset.size -gt $MaximumBytes) {
        Stop-DsrInstall ('Selected release asset is incomplete or exceeds its size limit: ' + $Name) 7
    }
    $url = 'https://api.github.com/repos/' + $Repository + '/releases/assets/' + $asset.id
    # An existing inventory member cannot be treated as an optional miss when
    # its download fails; do not hide deletion/authentication errors by trying
    # a different checksum format or a public anonymous path.
    $null = Invoke-DsrDownload $url $Destination -ApiAsset -MaximumBytes $MaximumBytes
    if ([IO.FileInfo]::new((Get-DsrPlainPath $Destination -File)).Length -ne $asset.size) {
        Stop-DsrInstall ('Release asset size changed after discovery: ' + $Name) 7
    }
    return $true
}

function Get-DsrChecksumNames {
    param($Binding)
    $number = if ($Binding.tag.StartsWith('v', [StringComparison]::Ordinal)) { $Binding.tag.Substring(1) } else { $Binding.tag }
    $names = @('SHA256SUMS', ($Binding.asset + '.sha256'), 'checksums.sha256', 'SHA256SUMS.txt', 'checksums.txt')
    $versioned = $Binding.tool + '-' + $number + '-SHA256SUMS.txt'
    if (Test-DsrWindowsName $versioned) { $names += $versioned }
    return $names
}

function Get-DsrSelectedChecksum {
    param([string]$Path, [string]$Asset, [string]$ChecksumName)
    $text = Read-DsrTextFile $Path
    $selected = [Collections.Generic.List[string]]::new()
    $names = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($line in ($text -split "`n")) {
        $line = $line.TrimEnd("`r")
        if (-not $line) { continue }
        if ($ChecksumName -ceq ($Asset + '.sha256') -and $line -cmatch '^[0-9a-fA-F]{64}$') {
            $selected.Add($line.ToLowerInvariant())
        } elseif ($line -cmatch '^([0-9a-fA-F]{64}) [ *]([^\r\n]+)$') {
            $hash = $Matches[1].ToLowerInvariant()
            $name = $Matches[2]
            if (-not (Test-DsrName $name) -or -not $names.Add($name)) { Stop-DsrInstall 'Unsafe or duplicate checksum entry' 7 }
            if ($name -ceq $Asset) { $selected.Add($hash) }
        } else { Stop-DsrInstall 'Malformed checksum evidence' 7 }
    }
    if ($selected.Count -ne 1) { Stop-DsrInstall 'Checksum evidence must select the exact payload exactly once' 7 }
    return $selected[0]
}

function Assert-DsrSignature {
    param([string]$Payload, [string]$Signature, [string]$PublicKey)
    if (-not $PublicKey) { return }
    $null = Get-DsrPlainPath $Signature -File
    $command = Get-Command minisign -CommandType Application -ErrorAction SilentlyContinue
    if ($null -eq $command) { Stop-DsrInstall 'The configured signing key requires Minisign; install it before retrying' 3 }
    $start = [Diagnostics.ProcessStartInfo]::new()
    $start.FileName = $command.Source
    $start.UseShellExecute = $false
    $start.RedirectStandardOutput = $true
    $start.RedirectStandardError = $true
    foreach ($argument in @('-Vm', $Payload, '-x', $Signature, '-P', $PublicKey, '-H')) { $start.ArgumentList.Add($argument) }
    $process = [Diagnostics.Process]::new()
    $process.StartInfo = $start
    try {
        if (-not $process.Start()) { Stop-DsrInstall 'Could not start Minisign' 3 }
        $output = $process.StandardOutput.ReadToEndAsync()
        $errorOutput = $process.StandardError.ReadToEndAsync()
        if (-not $process.WaitForExit(60000)) {
            $process.Kill($true)
            $process.WaitForExit()
            Stop-DsrInstall 'Minisign verification timed out' 7
        }
        $null = $output.GetAwaiter().GetResult()
        $null = $errorOutput.GetAwaiter().GetResult()
        if ($process.ExitCode -ne 0) { Stop-DsrInstall 'Minisign signature verification failed' 7 }
    } finally { $process.Dispose() }
}

function Assert-DsrPeMachine {
    param([string]$Path, [string]$Platform)
    $expected = @{ 'windows/amd64' = 0x8664; 'windows/arm64' = 0xaa64; 'windows/386' = 0x014c }[$Platform]
    $stream = Open-DsrReadFile $Path
    $reader = [IO.BinaryReader]::new($stream)
    try {
        if ($stream.Length -lt 96 -or $reader.ReadUInt16() -ne 0x5a4d) { Stop-DsrInstall 'Selected executable is not a PE image' 7 }
        $stream.Position = 0x3c
        $offset = $reader.ReadUInt32()
        if ($offset -lt 64 -or $offset -gt $stream.Length - 26) { Stop-DsrInstall 'Invalid PE header location' 7 }
        $stream.Position = $offset
        if ($reader.ReadUInt32() -ne 0x00004550 -or $reader.ReadUInt16() -ne $expected) {
            Stop-DsrInstall 'Executable machine does not match the selected Windows platform' 7
        }
        $stream.Position = $offset + 20
        $optionalSize = $reader.ReadUInt16()
        $characteristics = $reader.ReadUInt16()
        $magic = $reader.ReadUInt16()
        $expectedMagic = if ($Platform -ceq 'windows/386') { 0x10b } else { 0x20b }
        if ($optionalSize -lt 2 -or $offset + 24 + $optionalSize -gt $stream.Length -or
            ($characteristics -band 2) -eq 0 -or ($characteristics -band 0x2000) -ne 0 -or $magic -ne $expectedMagic) {
            Stop-DsrInstall 'Invalid executable PE image or incompatible optional header' 7
        }
    } finally { $reader.Dispose(); $stream.Dispose() }
}

function Expand-DsrPayload {
    param([string]$Payload, $Selection, [string]$Platform, [string]$Destination)
    $null = New-DsrPrivateDirectory $Destination
    if ($Selection.format -ceq 'none') {
        Copy-DsrNewFile $Payload ([IO.Path]::Combine($Destination, $Selection.binaries[0]))
    } else {
        $stream = Open-DsrReadFile $Payload
        $archive = $null
        try {
            $archive = [IO.Compression.ZipArchive]::new($stream, [IO.Compression.ZipArchiveMode]::Read, $true)
            if ($archive.Entries.Count -eq 0 -or $archive.Entries.Count -gt 10000) { Stop-DsrInstall 'Invalid ZIP entry count' 7 }
            $nodes = [Collections.Generic.Dictionary[string, string]]::new([StringComparer]::OrdinalIgnoreCase)
            $explicitNames = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
            $selected = @{}
            $expanded = 0L
            foreach ($entry in $archive.Entries) {
                $name = $entry.FullName
                $directory = $name.EndsWith('/', [StringComparison]::Ordinal)
                $path = if ($directory) { $name.Substring(0, $name.Length - 1) } else { $name }
                $parts = $path.Split('/')
                if (-not $path -or $path.Length -gt 1024 -or $parts.Count -gt 16 -or
                    -not $explicitNames.Add($path)) { Stop-DsrInstall 'Unsafe or duplicate ZIP member' 7 }
                foreach ($part in $parts) {
                    if (-not (Test-DsrWindowsName $part)) {
                        Stop-DsrInstall 'Unsafe Windows ZIP member path' 7
                    }
                }
                $type = ([long]$entry.ExternalAttributes -shr 16) -band 0xf000
                if (($type -ne 0 -and $type -ne 0x8000 -and $type -ne 0x4000) -or
                    ($entry.ExternalAttributes -band 0x400) -ne 0 -or
                    ($directory -and $type -eq 0x8000) -or (-not $directory -and $type -eq 0x4000)) {
                    Stop-DsrInstall 'Linked or unsupported ZIP member' 7
                }
                $cursor = ''
                for ($index = 0; $index -lt $parts.Count; $index++) {
                    $cursor = if ($cursor) { $cursor + '/' + $parts[$index] } else { $parts[$index] }
                    $kind = if ($index -lt $parts.Count - 1 -or $directory) { 'directory' } else { 'file' }
                    if ($nodes.ContainsKey($cursor)) {
                        if ($nodes[$cursor] -cne ('directory:' + $cursor) -or $kind -cne 'directory') {
                            Stop-DsrInstall 'Case-colliding ZIP paths or file/directory conflict' 7
                        }
                    } else { $nodes.Add($cursor, $kind + ':' + $cursor) }
                }
                $expanded += $entry.Length
                if ($entry.Length -lt 0 -or $entry.Length -gt $script:DsrMaximumPayloadBytes -or
                    $expanded -gt $script:DsrMaximumExpandedBytes -or ($directory -and $entry.Length -ne 0)) {
                    Stop-DsrInstall 'ZIP expanded size exceeds admission limits' 7
                }
                if (-not $directory) {
                    foreach ($binary in $Selection.binaries) {
                        if ($parts[-1].Equals($binary, [StringComparison]::OrdinalIgnoreCase)) {
                            if ($selected.ContainsKey($binary) -or $entry.Length -eq 0) { Stop-DsrInstall 'Missing or ambiguous executable ZIP member' 7 }
                            $selected[$binary] = $entry
                        }
                    }
                }
            }
            if ($selected.Count -ne $Selection.binaries.Count) { Stop-DsrInstall 'ZIP does not contain every selected executable' 7 }
            foreach ($binary in $Selection.binaries) {
                $entry = $selected[$binary]
                $incoming = $entry.Open()
                try {
                    $outgoing = New-DsrPrivateFile ([IO.Path]::Combine($Destination, $binary))
                    try {
                        $buffer = [byte[]]::new(1048576)
                        $written = 0L
                        while (($count = $incoming.Read($buffer, 0, $buffer.Length)) -gt 0) {
                            $written += $count
                            if ($written -gt $entry.Length) { Stop-DsrInstall 'ZIP member exceeds its declared size' 7 }
                            $outgoing.Write($buffer, 0, $count)
                        }
                        if ($written -ne $entry.Length) { Stop-DsrInstall 'Truncated ZIP executable' 7 }
                        $outgoing.Flush($true)
                    } finally { $outgoing.Dispose() }
                } finally { $incoming.Dispose() }
            }
        } finally {
            if ($null -ne $archive) { $archive.Dispose() }
            $stream.Dispose()
        }
    }
    foreach ($binary in $Selection.binaries) { Assert-DsrPeMachine ([IO.Path]::Combine($Destination, $binary)) $Platform }
}

function Get-DsrCacheReceipt {
    param([string]$Directory, $Binding, [string]$PublicKey)
    $null = Get-DsrPlainPath $Directory -Directory
    Assert-DsrCacheCustody $Directory
    $receipt = ConvertFrom-DsrJson (Read-DsrTextFile ([IO.Path]::Combine($Directory, 'cache.json')) 65536)
    Assert-DsrFields $receipt @('schema_version', 'policy_sha256', 'tool', 'repo', 'tag', 'platform', 'asset', 'format',
        'checksum_file', 'sha256', 'size_bytes', 'signature_sha256')
    foreach ($name in $Binding.Keys) {
        if ($receipt[$name] -cne $Binding[$name]) { Stop-DsrInstall 'Cached release belongs to a different installer selection' 7 }
    }
    if ($receipt.checksum_file -cnotin @(Get-DsrChecksumNames $Binding) -or
        $receipt.sha256 -cnotmatch '^[0-9a-f]{64}$' -or $receipt.size_bytes -isnot [long] -or
        $receipt.size_bytes -le 0 -or $receipt.size_bytes -gt $script:DsrMaximumPayloadBytes) {
        Stop-DsrInstall 'Malformed release cache receipt' 7
    }
    $payload = [IO.Path]::Combine($Directory, $Binding.asset)
    $expected = Get-DsrSelectedChecksum ([IO.Path]::Combine($Directory, $receipt.checksum_file)) $Binding.asset $receipt.checksum_file
    $evidence = Get-DsrFileEvidence $payload
    if ($expected -cne $receipt.sha256 -or $evidence.sha256 -cne $expected -or $evidence.size_bytes -ne $receipt.size_bytes) {
        Stop-DsrInstall 'Cached payload differs from its checksum evidence' 7
    }
    $allowed = @('cache.json', $Binding.asset, $receipt.checksum_file)
    if ($PublicKey) {
        $signature = [IO.Path]::Combine($Directory, ($Binding.asset + '.minisig'))
        if ($receipt.signature_sha256 -cnotmatch '^[0-9a-f]{64}$' -or
            (Get-DsrFileEvidence $signature).sha256 -cne $receipt.signature_sha256) { Stop-DsrInstall 'Cached signature evidence changed' 7 }
        Assert-DsrSignature $payload $signature $PublicKey
        $allowed += ($Binding.asset + '.minisig')
    } elseif ($null -ne $receipt.signature_sha256) { Stop-DsrInstall 'Unexpected cached signing policy' 7 }
    foreach ($entry in [IO.Directory]::EnumerateFileSystemEntries($Directory)) {
        if ([IO.Path]::GetFileName($entry) -cnotin $allowed) { Stop-DsrInstall 'Unexpected file in release cache' 7 }
        $null = Get-DsrPlainPath $entry -File
        Assert-DsrCacheCustody $entry
    }
    return $receipt
}

function Move-DsrInstalledFile {
    param([string]$Source, [string]$Destination)
    [IO.File]::Move($Source, $Destination, $true)
}

function Install-DsrExecutableFamily {
    param([string]$Source, [string]$Prefix, [string[]]$Names, [switch]$Yes)
    $prefixPath = New-DsrDirectoryChain $Prefix
    $lockPath = [IO.Path]::Combine($prefixPath, '.dsr-windows-install.lock')
    $null = Get-DsrPlainPath $lockPath
    $lease = $null
    $createdLease = $false
    try {
        $lease = New-DsrPrivateFile $lockPath
        $createdLease = $true
    } catch [IO.IOException] {
        try { $lease = [IO.FileStream]::new($lockPath, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::None) }
        catch [IO.IOException] { Stop-DsrInstall 'Installation directory is busy; retry after its active installer exits' 2 }
    }
    $stage = ''
    $committed = $false
    $retain = $false
    $previous = @{}
    $new = @{}
    $touched = [Collections.Generic.List[string]]::new()
    try {
        # The persistent file avoids deleting a kernel-locked pathname while
        # a later writer may already have opened that same lock generation.
        if ($createdLease) {
            $bytes = [Text.UTF8Encoding]::new($false).GetBytes('dsr-windows-install-lock-v1')
            $lease.Write($bytes, 0, $bytes.Length)
            $lease.Flush($true)
        } else {
            $lease.Position = 0
            $buffer = [byte[]]::new(64)
            $count = $lease.Read($buffer, 0, $buffer.Length)
            if ($lease.Length -ne $count -or [Text.Encoding]::UTF8.GetString($buffer, 0, $count) -cne 'dsr-windows-install-lock-v1') {
                Stop-DsrInstall 'Reserved installation lock contains unrelated data' 2
            }
        }
        foreach ($name in $Names) {
            $path = Get-DsrPlainPath ([IO.Path]::Combine($prefixPath, $name))
            if ([IO.Directory]::Exists($path)) { Stop-DsrInstall 'An executable destination is a directory' 2 }
            if ([IO.File]::Exists($path)) {
                if (-not $Yes) {
                    if ($env:CI -eq '1' -or [Console]::IsInputRedirected) { Stop-DsrInstall 'Existing executables require -Yes for replacement' 2 }
                    $answer = Read-Host ('Replace ' + $path + '? [y/N]')
                    if ($answer -cnotin @('y', 'Y')) { Stop-DsrInstall 'Replacement was not authorized' 2 }
                }
                $previous[$name] = Get-DsrFileEvidence $path
            } else { $previous[$name] = $null }
        }
        $stage = New-DsrPrivateDirectory ([IO.Path]::Combine($prefixPath, ('.dsr-install-' + [Guid]::NewGuid().ToString('N'))))
        $fresh = New-DsrPrivateDirectory ([IO.Path]::Combine($stage, 'new'))
        $backups = New-DsrPrivateDirectory ([IO.Path]::Combine($stage, 'old'))
        foreach ($name in $Names) {
            Copy-DsrNewFile ([IO.Path]::Combine($Source, $name)) ([IO.Path]::Combine($fresh, $name))
            $new[$name] = Get-DsrFileEvidence ([IO.Path]::Combine($fresh, $name))
            if ($null -ne $previous[$name]) {
                Copy-DsrNewFile ([IO.Path]::Combine($prefixPath, $name)) ([IO.Path]::Combine($backups, $name))
                $backup = Get-DsrFileEvidence ([IO.Path]::Combine($backups, $name))
                if ($backup.sha256 -cne $previous[$name].sha256 -or $backup.size_bytes -ne $previous[$name].size_bytes) {
                    Stop-DsrInstall 'Existing executable changed before backup completed' 7
                }
            }
        }
        foreach ($name in $Names) {
            $path = Get-DsrPlainPath ([IO.Path]::Combine($prefixPath, $name))
            if ($null -eq $previous[$name]) {
                if ([IO.File]::Exists($path) -or [IO.Directory]::Exists($path)) { Stop-DsrInstall 'An executable appeared during installation' 2 }
            } else {
                $observed = Get-DsrFileEvidence $path
                if ($observed.sha256 -cne $previous[$name].sha256 -or $observed.size_bytes -ne $previous[$name].size_bytes) {
                    Stop-DsrInstall 'An installed executable changed during installation' 7
                }
            }
            $touched.Add($name)
            Move-DsrInstalledFile ([IO.Path]::Combine($fresh, $name)) $path
        }
        $results = @()
        foreach ($name in $Names) {
            $path = Get-DsrPlainPath ([IO.Path]::Combine($prefixPath, $name)) -File
            $observed = Get-DsrFileEvidence $path
            if ($observed.sha256 -cne $new[$name].sha256 -or $observed.size_bytes -ne $new[$name].size_bytes) {
                Stop-DsrInstall 'Final installed executable differs from its staged bytes' 7
            }
            $results += @{ name = $name; path = $path; sha256 = $observed.sha256; size_bytes = $observed.size_bytes }
        }
        $committed = $true
        return ,$results
    } finally {
        if (-not $committed -and $stage) {
            for ($index = $touched.Count - 1; $index -ge 0; $index--) {
                $name = $touched[$index]
                $path = [IO.Path]::Combine($prefixPath, $name)
                try {
                    $null = Get-DsrPlainPath $path
                    if ([IO.Directory]::Exists($path)) { throw 'Destination became a directory' }
                    if ([IO.File]::Exists($path)) {
                        $observed = Get-DsrFileEvidence $path
                        if ($null -ne $previous[$name] -and $observed.sha256 -ceq $previous[$name].sha256 -and
                            $observed.size_bytes -eq $previous[$name].size_bytes) { continue }
                        if ($observed.sha256 -cne $new[$name].sha256 -or $observed.size_bytes -ne $new[$name].size_bytes) {
                            throw 'Destination changed outside this transaction'
                        }
                    }
                    if ($null -ne $previous[$name]) { [IO.File]::Move([IO.Path]::Combine($stage, 'old', $name), $path, $true) }
                    elseif ([IO.File]::Exists($path)) { [IO.File]::Delete($path) }
                } catch {
                    $retain = $true
                    Write-DsrInstallLog ('Rollback could not restore ' + $name + '; recovery files retained at ' + $stage)
                }
            }
        }
        try {
            if ($stage -and -not $retain) {
                try { Remove-DsrPrivateTree $stage }
                catch { Write-DsrInstallLog ('Private transaction staging retained for inspection: ' + $stage) }
            }
        } finally { if ($null -ne $lease) { $lease.Dispose() } }
        if ($retain) { Stop-DsrInstall ('Installation failed; recovery files retained at ' + $stage) 7 }
    }
}

function Invoke-DsrWindowsInstaller {
    [CmdletBinding()]
    param([string]$Version = '', [string]$Prefix = '', [string]$CacheDir = '',
          [switch]$Offline, [switch]$Yes, [switch]$Json, [switch]$Help)
    $work = ''
    $tool = ''
    try {
        if ($PSVersionTable.PSVersion -lt [Version]'7.4') { Stop-DsrInstall 'PowerShell 7.4 or newer is required' 3 }
        $policyEnvelope = Get-DsrInstallPolicy
        $policy = $policyEnvelope.value
        $tool = $policy.tool
        if ($Help) {
            $text = @"
Install $tool on native Windows using verified release payloads.

Options:
  -Version TAG   Exact tag (numeric 1.2.3 also accepts v1.2.3); default: latest
  -Prefix DIR    Destination directory; default: LocalAppData/Programs/$tool/bin
  -CacheDir DIR  Persistent verified download cache
  -Offline       No network; requires -Version and complete cached evidence
  -Yes           Authorize replacement of existing selected executables
  -Json          Emit one machine-readable result
  -Verbose       Print additional diagnostics to stderr
  -Help          Show this help

Every selected executable is checked before replacement. Configured signatures
require Minisign. This installer never executes downloaded payloads or edits PATH.
Private releases use DSR_GH_TOKEN, GITHUB_TOKEN, then GH_TOKEN, with Contents read
permission. Credentials are sent only to the configured repository's GitHub API.
"@
            if ($Json) { [Console]::Out.WriteLine((@{ tool = $tool; status = 'help'; help = $text } | ConvertTo-Json -Compress)) }
            else { [Console]::Out.WriteLine($text) }
            return 0
        }
        $platform = Get-DsrHostPlatform
        if (-not $policy.platforms.Contains($platform)) { Stop-DsrInstall ('No configured release for ' + $platform) 3 }
        $selection = $policy.platforms[$platform]
        if ($Offline -and -not $Version) { Stop-DsrInstall '-Offline requires an explicit -Version' }
        if ($Version -and -not (Test-DsrName $Version)) { Stop-DsrInstall 'Invalid release version' }
        $localAppData = [Environment]::GetFolderPath([Environment+SpecialFolder]::LocalApplicationData)
        if (-not $Prefix) { $Prefix = [IO.Path]::Combine($localAppData, 'Programs', $tool, 'bin') }
        if (-not $CacheDir) { $CacheDir = [IO.Path]::Combine($localAppData, 'dsr', 'cache', 'installers') }
        $prefixPath = Get-DsrPlainPath $Prefix
        $cacheRoot = Get-DsrPlainPath $CacheDir
        if (Test-DsrPathsOverlap $prefixPath $cacheRoot) { Stop-DsrInstall 'Installation and download cache paths must not overlap' }
        if (-not $Offline) { $null = New-DsrDirectoryChain $cacheRoot }
        else { $null = Get-DsrPlainPath $cacheRoot -Directory }
        Assert-DsrCacheCustody $cacheRoot
        $release = $null
        if (-not $Version) {
            $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-download-' + [Guid]::NewGuid().ToString('N'))))
            $latest = [IO.Path]::Combine($work, 'latest.json')
            $null = Invoke-DsrDownload ('https://api.github.com/repos/' + $policy.repo + '/releases/latest') $latest -MaximumBytes 8388608
            $release = ConvertFrom-DsrJson (Read-DsrTextFile $latest)
            if ($release -isnot [System.Collections.IDictionary] -or -not $release.Contains('tag_name') -or
                -not (Test-DsrName $release.tag_name) -or ($release.Contains('draft') -and $release.draft -ne $false)) {
                Stop-DsrInstall 'Invalid latest-release identity' 7
            }
            $tag = $release.tag_name
        } else { $tag = if ($Version -cmatch '^[0-9]') { 'v' + $Version } else { $Version } }
        $number = if ($tag.StartsWith('v', [StringComparison]::Ordinal)) { $tag.Substring(1) } else { $tag }
        $asset = $selection.name.Replace('${version}', $number)
        if (-not (Test-DsrWindowsName $asset)) { Stop-DsrInstall 'Resolved payload name is unsafe' }
        Write-DsrInstallVerbose ('Selected ' + $platform + ' release ' + $tag + ': ' + $asset)
        $binding = [ordered]@{ schema_version = 1; policy_sha256 = $policyEnvelope.sha256; tool = $tool; repo = $policy.repo;
            tag = $tag; platform = $platform; asset = $asset; format = $selection.format }
        if ($asset -iin @('cache.json') + @(Get-DsrChecksumNames $binding)) {
            Stop-DsrInstall 'Selected payload name collides with release verification metadata'
        }
        $identity = Get-DsrBytesHash ([Text.Encoding]::UTF8.GetBytes(($binding | ConvertTo-Json -Compress)))
        $cache = [IO.Path]::Combine($cacheRoot, ($tool + '-' + $identity))
        $null = Get-DsrPlainPath $cache
        if ([IO.Directory]::Exists($cache)) {
            Write-DsrInstallVerbose 'Revalidating the exact cached release and its proof'
            $receipt = Get-DsrCacheReceipt $cache $binding $policy.public_key
        } elseif ($Offline) { Stop-DsrInstall 'No complete verified cache exists for this exact release selection' 7 }
        else {
            if (-not $work) { $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-download-' + [Guid]::NewGuid().ToString('N')))) }
            $inventory = $null
            if (Get-DsrGitHubToken) {
                Write-DsrInstallVerbose 'Resolving the selected authenticated GitHub release and complete asset inventory'
                if ($null -eq $release) {
                    $metadata = [IO.Path]::Combine($work, 'release.json')
                    $releaseUrl = 'https://api.github.com/repos/' + $policy.repo + '/releases/tags/' + [Uri]::EscapeDataString($tag)
                    $null = Invoke-DsrDownload $releaseUrl $metadata -MaximumBytes 8388608
                    $release = ConvertFrom-DsrJson (Read-DsrTextFile $metadata)
                }
                Assert-DsrReleaseIdentity $release $tag
                $inventory = Get-DsrReleaseAssets $policy.repo $release.id $work
            } else { Write-DsrInstallVerbose 'Downloading the selected public GitHub release payload' }
            $download = New-DsrPrivateDirectory ([IO.Path]::Combine($work, 'release'))
            $payload = [IO.Path]::Combine($download, $asset)
            $null = Save-DsrReleaseAsset $policy.repo $tag $asset $payload $inventory -MaximumBytes $script:DsrMaximumPayloadBytes
            $checksumName = ''
            foreach ($candidate in @(Get-DsrChecksumNames $binding)) {
                if (Save-DsrReleaseAsset $policy.repo $tag $candidate ([IO.Path]::Combine($download, $candidate)) $inventory -Optional -MaximumBytes 8388608) {
                    $checksumName = $candidate
                    break
                }
            }
            if (-not $checksumName) { Stop-DsrInstall 'No checksum evidence was published for this payload' 7 }
            $expected = Get-DsrSelectedChecksum ([IO.Path]::Combine($download, $checksumName)) $asset $checksumName
            $evidence = Get-DsrFileEvidence $payload
            if ($evidence.size_bytes -eq 0 -or $evidence.sha256 -cne $expected) { Stop-DsrInstall 'Downloaded payload checksum mismatch' 7 }
            $signatureHash = $null
            if ($policy.public_key) {
                $signature = [IO.Path]::Combine($download, ($asset + '.minisig'))
                $null = Save-DsrReleaseAsset $policy.repo $tag ($asset + '.minisig') $signature $inventory -MaximumBytes 65536
                Assert-DsrSignature $payload $signature $policy.public_key
                $signatureHash = (Get-DsrFileEvidence $signature).sha256
            }
            $receipt = [ordered]@{}
            foreach ($name in $binding.Keys) { $receipt[$name] = $binding[$name] }
            $receipt.checksum_file = $checksumName
            $receipt.sha256 = $expected
            $receipt.size_bytes = $evidence.size_bytes
            $receipt.signature_sha256 = $signatureHash
            Write-DsrNewTextFile ([IO.Path]::Combine($download, 'cache.json')) ($receipt | ConvertTo-Json -Compress)
            $null = Get-DsrCacheReceipt $download $binding $policy.public_key
            try { [IO.Directory]::Move($download, $cache) }
            catch [IO.IOException] {
                if (-not [IO.Directory]::Exists($cache)) { throw }
                $existing = Get-DsrCacheReceipt $cache $binding $policy.public_key
                if ($existing.sha256 -cne $receipt.sha256 -or $existing.size_bytes -ne $receipt.size_bytes) {
                    Stop-DsrInstall 'Concurrent download selected different release bytes' 2
                }
                $receipt = $existing
            }
        }
        if (-not $work) { $work = New-DsrPrivateDirectory ([IO.Path]::Combine($cacheRoot, ('.dsr-install-stage-' + [Guid]::NewGuid().ToString('N')))) }
        # Copy all proof into a private generation, then authenticate those
        # exact bytes. A cache pathname is never a reservation for extraction.
        $privateRelease = New-DsrPrivateDirectory ([IO.Path]::Combine($work, 'verified-release'))
        $proofNames = @('cache.json', $asset, $receipt.checksum_file)
        if ($policy.public_key) { $proofNames += ($asset + '.minisig') }
        foreach ($name in $proofNames) {
            Copy-DsrNewFile ([IO.Path]::Combine($cache, $name)) ([IO.Path]::Combine($privateRelease, $name))
        }
        $copied = Get-DsrCacheReceipt $privateRelease $binding $policy.public_key
        if ($copied.sha256 -cne $receipt.sha256 -or $copied.size_bytes -ne $receipt.size_bytes) {
            Stop-DsrInstall 'Cached release changed while its private copy was prepared' 7
        }
        $payload = [IO.Path]::Combine($privateRelease, $asset)
        $expanded = [IO.Path]::Combine($work, 'expanded')
        Expand-DsrPayload $payload $selection $platform $expanded
        # Recheck all original proof after extraction and before the first
        # destination write; an earlier successful hash is not a reservation.
        $null = Get-DsrCacheReceipt $privateRelease $binding $policy.public_key
        Write-DsrInstallVerbose 'Checksum, configured signature, archive and executable admission completed'
        $installed = Install-DsrExecutableFamily $expanded $prefixPath $selection.binaries -Yes:$Yes
        $primary = $policy.binary_name
        if (-not $primary.EndsWith('.exe', [StringComparison]::OrdinalIgnoreCase)) { $primary += '.exe' }
        $primaryRow = @($installed | Where-Object { $_.name.Equals($primary, [StringComparison]::OrdinalIgnoreCase) })[0]
        $result = @{ tool = $tool; repository = $policy.repo; status = 'success'; version = $tag; platform = $platform;
            target_triple = $selection.target_triple; path = $primaryRow.path; binaries = @($installed);
            cache = @{ path = $cache; offline = [bool]$Offline }; signature_verified = [bool]$policy.public_key; exit_code = 0 }
        Write-DsrInstallLog ('Installed ' + $tool + ' ' + $tag + ' (' + $installed.Count + ' executable(s))')
        if ($Json) { [Console]::Out.WriteLine(($result | ConvertTo-Json -Depth 12 -Compress)) }
        else { [Console]::Out.WriteLine($primaryRow.path) }
        return 0
    } catch {
        $code = 7
        if ($_.Exception.Data.Contains('DsrExitCode')) { $code = [int]$_.Exception.Data['DsrExitCode'] }
        Write-DsrInstallLog $_.Exception.Message
        if ($Json) {
            [Console]::Out.WriteLine((@{ tool = $tool; status = 'error'; error = $_.Exception.Message; exit_code = $code } | ConvertTo-Json -Compress))
        }
        return $code
    } finally {
        if ($work) {
            try { Remove-DsrPrivateTree $work }
            catch { Write-DsrInstallLog ('Private staging retained for inspection: ' + $work) }
        }
    }
}

# DSR_WINDOWS_INSTALL_DISPATCH: tests replace only host/HTTP boundaries before this call.
exit (Invoke-DsrWindowsInstaller @PSBoundParameters)
